-- Disposable CI only: transactional outbox for prospective external audit.
-- Not a production migration or independent immutable audit sink.
-- Generated by the audit INSERT in the same transaction as approval consumption.
CREATE TABLE IF NOT EXISTS finance_key_audit_outbox_candidate (
  audit_id bigint PRIMARY KEY REFERENCES finance_key_approval_audit_candidate(id),
  event_id text NOT NULL UNIQUE,
  payload jsonb NOT NULL,
  delivered_at timestamptz,
  delivery_attempts integer NOT NULL DEFAULT 0 CHECK (delivery_attempts >= 0),
  CHECK (jsonb_typeof(payload) = 'object')
);
REVOKE ALL ON finance_key_audit_outbox_candidate FROM PUBLIC;

CREATE OR REPLACE FUNCTION finance_key_audit_enqueue_candidate()
RETURNS trigger
LANGUAGE plpgsql
AS $enqueue$
BEGIN
  INSERT INTO finance_key_audit_outbox_candidate(audit_id, event_id, payload)
  VALUES (
    NEW.id,
    'finance-approval-audit-' || NEW.id::text,
    jsonb_build_object(
      'event_id', 'finance-approval-audit-' || NEW.id::text,
      'approval_id', NEW.approval_id,
      'action', NEW.action,
      'recorded_at', NEW.recorded_at
    )
  );
  RETURN NEW;
END
$enqueue$;

CREATE TRIGGER finance_key_audit_enqueue_candidate
AFTER INSERT ON finance_key_approval_audit_candidate
FOR EACH ROW EXECUTE FUNCTION finance_key_audit_enqueue_candidate();
